  { unsigned char const bytes[] = {0x21u, 0x00u};        assert(unicode(bytes, format::X_ADOBE_ZAPF_DINGBATS_ENCODING) == 0x2701u); }
  // TSCII can expand a single source byte to four Unicode scalar values.
  {
    unsigned char const bytes[] = {0x82u, 0u};
    struct state iterator = {};
    iterator.reset(format::TSCII);
    assert(unicode(bytes, format::TSCII, &iterator) == 0x0BB8u);
    assert(unicode(bytes, format::TSCII, &iterator) == 0x0BCDu);
    assert(unicode(bytes, format::TSCII, &iterator) == 0x0BB0u);
    assert(unicode(bytes, format::TSCII, &iterator) == 0x0BC0u);
    assert(iterator.scalars.count == 0u);
    assert(iterator.offset == 1u);
  }

  // BOM encoding: U+FEFF in UTF-7/8/16/32; unavailable in legacy charsets.
  unsigned char bomBytes[5] = {};
  assert(bom(format::UTF_8, bomBytes, sizeof(bomBytes)) == 3u);
  assert(bomBytes[0] == 0xEFu and bomBytes[1] == 0xBBu and bomBytes[2] == 0xBFu);
  assert(bom(format::UTF_16, bomBytes, sizeof(bomBytes), ENDIAN_BIG) == 2u);
  assert(bomBytes[0] == 0xFEu and bomBytes[1] == 0xFFu);
  assert(bom(format::UTF_16, bomBytes, sizeof(bomBytes), ENDIAN_LITTLE) == 2u);
  assert(bomBytes[0] == 0xFFu and bomBytes[1] == 0xFEu);
  assert(bom(format::UTF_32, bomBytes, sizeof(bomBytes), ENDIAN_BIG) == 4u);
  assert(bomBytes[0] == 0x00u and bomBytes[1] == 0x00u and bomBytes[2] == 0xFEu and bomBytes[3] == 0xFFu);
  assert(bom(format::UTF_32LE, bomBytes, sizeof(bomBytes)) == 4u);
  assert(bomBytes[0] == 0xFFu and bomBytes[1] == 0xFEu and bomBytes[2] == 0x00u and bomBytes[3] == 0x00u);
  assert(bom(format::UTF_7, bomBytes, sizeof(bomBytes)) == 5u);
  assert(bomBytes[0] == '+' and bomBytes[1] == '/' and bomBytes[2] == 'v' and bomBytes[3] == '8' and bomBytes[4] == '-');
  assert(bom(format::UTF_8, bomBytes, 2u) == state::NO_SPACE);
  unsigned char const utf7Bom[] = {'+', '/', 'v', '8', '-', 0u};
  assert(unicode(utf7Bom, format::UTF_7) == 0xFEFFu);
  assert(bom(format::UTF_7_IMAP, bomBytes) == state::UNSUPPORTED);
  assert(bom(format::WINDOWS_1252, bomBytes) == state::UNSUPPORTED);
  assert(bom(format::UTF_16, bomBytes, 0u, ENDIAN_MIXED) == state::UNSUPPORTED);

  unsigned char const pairedUtf16[] = {0x3Du, 0xD8u, 0x00u, 0xDEu, 0u, 0u};
  struct state pairedCursor = {}; pairedCursor.reset(format::UTF_16LE);
  assert(unicode(pairedUtf16, format::UTF_16LE, &pairedCursor) == 0x1F600u);
  assert(pairedCursor.utf16.surrogate.high == 0xD83Du and pairedCursor.utf16.surrogate.low == 0xDE00u);
  pairedCursor.reset(format::UTF_16LE);
  assert(pairedCursor.utf16.surrogate.high == 0u and pairedCursor.utf16.surrogate.low == 0u and pairedCursor.offset == 0u);
  assert((state::SCSU_UNICODE & (state::ISO_2022_G1_DESIGNATED | state::ISO_2022_G2_DESIGNATED | state::ISO_2022_G3_DESIGNATED | state::ISO_2022_SHIFTED)) == 0u);

  // The encoding selects the active member; reset allows reuse of the same union.
  {
    unsigned char const big5Pair[] = {0x88u, 0x62u, 0u};
    unsigned char const utf7Pair[] = {'+', 'A', 'E', 'I', 'A', 'Q', 'w', '-', 0u};
    struct state reused = {};
    reused.reset(format::BIG5_HKSCS);
    assert(unicode(big5Pair, format::BIG5_HKSCS, &reused) == 0x00CAu);
    assert(reused.scalars.count == 1u);
    reused.reset(format::UTF_7);
    assert(reused.utf7.remainingCount == 0u and reused.utf7.byteCount == 0u);
    assert(unicode(utf7Pair, format::UTF_7, &reused) == 'B');
    assert(reused.utf7.remainingCount == 1u);
    assert(unicode(&utf7Pair[reused.offset], format::UTF_7, &reused) == 'C');
    // A pending UTF-7 run depends on caller-supplied bytes, not a stored pointer.
    unsigned char const utf7Copy[] = {'+', 'A', 'E', 'I', 'A', 'Q', 'w', '-', 0u};
    reused.reset(format::UTF_7);
    assert(unicode(utf7Pair, format::UTF_7, &reused) == 'B');
    assert(unicode(utf7Copy, format::UTF_7, &reused) == 'C');
    assert(reused.offset == 8u and reused.utf7.remainingCount == 0u);
    reused.reset(format::UTF_16LE);
    assert(reused.utf16.surrogate.high == 0u and reused.utf16.surrogate.low == 0u);
    assert(unicode(pairedUtf16, format::UTF_16LE, &reused) == 0x1F600u);
    assert(reused.utf16.surrogate.high == 0xD83Du and reused.utf16.surrogate.low == 0xDE00u);
    reused.reset(format::BIG5_HKSCS);
    assert(reused.scalars.count == 0u);
    assert(unicode(big5Pair, format::BIG5_HKSCS, &reused) == 0x00CAu);
  }

